package dev.arya.messenger.security

import android.security.keystore.KeyGenParameterSpec
import android.security.keystore.KeyProperties
import java.security.KeyStore
import javax.crypto.Cipher
import javax.crypto.KeyGenerator
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec

/**
 * AES-256-GCM wrapping vault backed by a non-exportable Android Keystore key.
 *
 * Each alias owns an independent Keystore key, so unrelated secrets are never wrapped
 * under the same key. The IV is generated by Android Keystore and stored as the record
 * prefix because supplying our own IV can be rejected when randomized encryption is enforced.
 */
internal class KeystoreAesVault(private val alias: String) : SecretVault {

    init {
        require(alias.isNotBlank()) { "Keystore alias must not be blank" }
    }

    override fun seal(plaintext: ByteArray, aad: ByteArray): ByteArray {
        val cipher = Cipher.getInstance(TRANSFORMATION)
        cipher.init(Cipher.ENCRYPT_MODE, getOrCreateKey())
        val nonce = requireNotNull(cipher.iv) { "Android Keystore did not provide a GCM IV" }
        require(nonce.size == NONCE_SIZE) { "Unexpected Android Keystore GCM IV size" }
        cipher.updateAAD(aad)
        return nonce + cipher.doFinal(plaintext)
    }

    override fun open(sealed: ByteArray, aad: ByteArray): ByteArray {
        require(sealed.size > NONCE_SIZE + TAG_SIZE) { "Sealed value is too short" }
        val nonce = sealed.copyOfRange(0, NONCE_SIZE)
        val ciphertext = sealed.copyOfRange(NONCE_SIZE, sealed.size)
        return Cipher.getInstance(TRANSFORMATION).run {
            init(Cipher.DECRYPT_MODE, getOrCreateKey(), GCMParameterSpec(TAG_BITS, nonce))
            updateAAD(aad)
            doFinal(ciphertext)
        }
    }

    private fun getOrCreateKey(): SecretKey {
        val store = KeyStore.getInstance(KEYSTORE).apply { load(null) }
        (store.getKey(alias, null) as? SecretKey)?.let { return it }
        return KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, KEYSTORE).run {
            init(
                KeyGenParameterSpec.Builder(alias, KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT)
                    .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
                    .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
                    .setKeySize(256)
                    .build()
            )
            generateKey()
        }
    }

    companion object {
        const val NONCE_SIZE = 12
        const val TAG_SIZE = 16
        private const val TAG_BITS = 128
        private const val KEYSTORE = "AndroidKeyStore"
        private const val TRANSFORMATION = "AES/GCM/NoPadding"
    }
}
